# Experiment 3C: average-score bar chart using base R graphics.
source("r/common.R"); d<-load_students(); avgs<-colMeans(d[subjects]); png(save_plot_path("3C_base_bar_chart.png"),1100,700,res=140); barplot(avgs,main="Average Subject Scores",xlab="Subject",ylab="Average score",ylim=c(0,100),col=c("#4776A8","#55A889","#D98B55"),border=NA); abline(h=mean(avgs),lty=2,col="grey30",lwd=2); legend("topleft",sprintf("Overall mean: %.1f",mean(avgs)),lty=2,col="grey30",bty="n"); dev.off(); print(round(avgs,2))
